function renderPointList(query=''){const found=expandedPoints.filter(p=>(p.name+' '+p.query).toLowerCase().includes(query.toLowerCase()));$('#point-count').textContent=`${found.length} 个`;$('#point-items').innerHTML=found.map(p=>`<button class="point-item" data-point="${p.id}"><img src="${p.image}" alt="${esc(p.imageLabel)}" loading="lazy"><span><strong>${esc(p.name)}</strong><small>${esc(p.kind==='optional'?'备选／冬季有条件开放':p.kind==='airport'?'机场':p.kind==='transport'?'交通与集合点':p.kind==='stay'?'住宿区域':'行程点位')} · DAY ${p.days.map(n=>String(n).padStart(2,'0')).join(' / ')}</small><small>Google 评分未接入 · 查看详情 ↗</small></span></button>`).join('')||'<p style="padding:24px">没有找到匹配的点位</p>';}
function openPoint(p){lastFocus=document.activeElement;$('#point-scrim').hidden=false;$('#point-sheet').hidden=false;const gmap='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.query);const directions='https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(p.query);$('#point-sheet').innerHTML=`<div class="point-cover"><img src="${p.image}" alt="${esc(p.imageLabel)}"><button class="icon-button point-close" data-close-point aria-label="关闭点位详情"><svg class="point-close-icon" viewBox="0 0 24 24" width="14" height="14" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg></button></div><div class="point-body"><span class="eyebrow">${esc(p.countryName)} / ${esc(p.kind==='optional'?'OPTIONAL STOP':'ON THE ROUTE')}</span><h2>${esc(p.name)}</h2><div class="rating">☆ Google 评分未接入 <a href="${gmap}" target="_blank" rel="noopener noreferrer">查看实时评分 ↗</a></div><div class="point-days">${p.days.map(n=>`<a href="#day/${n}" data-point-day>DAY ${String(n).padStart(2,'0')}</a>`).join('')}</div><p>${esc(p.description||'此地点出现在原行程中。具体停留安排与注意事项请查看对应日期的完整行程。')}</p>${p.cityProfile?`<div class="city-introduction"><h3>本次停留</h3><p>${esc(p.cityProfile.plan)}</p><h3>城市与区域看点</h3><ul>${p.cityProfile.highlights.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><a class="city-source" href="${esc(p.cityProfile.source)}" target="_blank" rel="noopener noreferrer">城市／区域官方介绍 ↗</a></div>`:''}${p.kind==='optional'?'<p>原行程中的顺路／备选点位，是否前往取决于道路开放、天气与当天时间。</p>':''}${p.kind==='stay'?'<p>此标记为住宿建议区域，具体酒店尚未预订。</p>':''}<p style="font-size:11px">地图标记用于位置参考；正式导航与活动集合点以地图和预订凭证为准。</p><a class="google-button" href="${gmap}" target="_blank" rel="noopener noreferrer">在 Google Maps 中打开 ↗</a><a class="secondary-google" href="${directions}" target="_blank" rel="noopener noreferrer">使用 Google Maps 导航</a><p style="font-size:10px">图片：${esc(p.imageLabel)}${p.imageReference?'（当日行程参考图）':''}${p.imageSource?` · <a href="${esc(p.imageSource)}" target="_blank" rel="noopener noreferrer">查看来源</a>`:''}</p></div>`;document.body.style.overflow='hidden';$('#point-sheet button').focus();}
function closePoint(){if($('#point-sheet').hidden)return;$('#point-sheet').hidden=true;$('#point-scrim').hidden=true;if($('#map-modal').hidden)document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus();}
function openNav(){$('#sidebar').classList.add('open');$('#nav-scrim').hidden=false;document.body.style.overflow='hidden';$('#sidebar .home-icon').focus();}
function closeNav(){keepNavOnRoute=false;$('#sidebar').classList.remove('open');$('#nav-scrim').hidden=true;if($('#map-modal').hidden&&$('#point-sheet').hidden)document.body.style.overflow='';}
document.addEventListener('click',e=>{const exp=e.target.closest('[data-expand]');if(exp)openMap(exp.dataset.expand);const pt=e.target.closest('[data-point]');if(pt){const p=expandedPoints.find(p=>p.id===pt.dataset.point)||points.find(p=>p.id===pt.dataset.point);if(expanded){expanded.map.flyTo([p.coord[1],p.coord[0]],Math.max(expanded.map.getZoom(),12),{duration:.5});}openPoint(p);}if(e.target.closest('[data-close-point]'))closePoint();const st=e.target.closest('[data-side-country]');if(st){setCountry(st.dataset.sideCountry);if(view.type!=='home'){const nextHash='#country/'+st.dataset.sideCountry;keepNavOnRoute=location.hash!==nextHash&&$('#sidebar').classList.contains('open');location.hash=nextHash;}else if(innerWidth>860){scrollCountry(st.dataset.sideCountry);}}const ht=e.target.closest('[data-home-country]');if(ht)scrollCountry(ht.dataset.homeCountry);if(e.target.closest('#sidebar a'))closeNav();});
function scrollCountry(id){setCountry(id);navLock=true;$('#section-'+id)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});setTimeout(()=>navLock=false,1000);}
$('#menu-open').onclick=openNav;$('#nav-scrim').onclick=closeNav;$('#map-close').onclick=closeMap;$('#point-scrim').onclick=closePoint;$('#points-toggle').onclick=()=>{$('#map-list').classList.toggle('closed');$('#points-toggle').setAttribute('aria-expanded',String(!$('#map-list').classList.contains('closed')));setTimeout(()=>expanded?.map.invalidateSize(),260);};$('#point-search').oninput=e=>renderPointList(e.target.value);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#point-sheet').hidden)closePoint();else if(!$('#map-modal').hidden)closeMap();else closeNav();}if(e.key==='Tab'){const scope=!$('#point-sheet').hidden?$('#point-sheet'):!$('#map-modal').hidden?$('#map-modal'):$('#sidebar').classList.contains('open')?$('#sidebar'):null;if(scope){const focusable=[...scope.querySelectorAll('a,button,input,[tabindex="0"]')].filter(n=>n.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}});
window.addEventListener('hashchange',route);
Promise.all([fetch('data.json?v=10').then(r=>{if(!r.ok)throw Error('data');return r.json();}),fetch('points.json?v=2').then(r=>{if(!r.ok)throw Error('points');return r.json();}),fetch('experiences.json?v=2').then(r=>{if(!r.ok)throw Error('experiences');return r.json();})]).then(([cs,ps,xs])=>{experiences=xs;countries=cs;days=cs.flatMap(c=>c.days);points=ps;buildPlaceLinks();route();}).catch(()=>{$('#main').innerHTML='<div class="loading"><h1>行程暂时无法加载</h1><p>请检查网络后刷新页面。</p><button onclick="location.reload()">重新加载</button></div>';});

function renderExperience(item){const c=countryById(item.country),photo=item.photos[0];$('#main').innerHTML=`<div class="page-wrap experience-page" style="--theme:${c.color}"><nav class="breadcrumb"><a href="#budget">预算单</a><span>/ 游玩项目</span></nav><article class="experience-card"><div class="experience-gallery" data-experience="${item.id}" data-photo-index="0"><div class="experience-stage"><img id="experience-photo" src="${photo.src}" alt="${esc(photo.label)}" fetchpriority="high"><button class="gallery-arrow gallery-prev" data-gallery-step="-1" aria-label="上一张图片">‹</button><button class="gallery-arrow gallery-next" data-gallery-step="1" aria-label="下一张图片">›</button><span class="gallery-count" aria-live="polite">1 / ${item.photos.length}</span></div><div class="gallery-caption" id="gallery-caption">${esc(photo.label)}</div><div class="experience-thumbnails" aria-label="选择项目图片">${item.photos.map((p,i)=>`<button data-gallery-photo="${i}" aria-label="查看图片${i+1}：${esc(p.label)}" aria-pressed="${i===0}"><img src="${p.src}" alt="" loading="lazy"></button>`).join('')}</div></div><div class="experience-content"><p class="experience-location">${esc(item.location)} · DAY ${String(item.day).padStart(2,'0')}</p>${item.excluded?'<p class="experience-status">已排除 · 不计入预算</p>':''}<h1>${esc(item.title)}</h1><p class="experience-intro">${esc(item.intro)}</p><div class="experience-facts"><div><small>游玩时长</small><strong>${esc(item.duration)}</strong></div><div><small>${item.excluded?'原参考价格':'每人预算'}</small><strong>${money(item.price)}<small>／人</small></strong></div></div><section><h2>项目体验</h2><ul>${item.includes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section><h2>集合与安排</h2><p>${esc(item.meeting)}</p></section><section><h2>价格说明</h2><p>${esc(item.priceNote)}</p></section><section><h2>行前准备</h2><ul>${item.notes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><div class="experience-links"><a href="#day/${item.day}">查看 DAY ${String(item.day).padStart(2,'0')} 行程 ↗</a><a href="${esc(item.url)}" target="_blank" rel="noopener">${esc(item.operator)} 项目官网 ↗</a></div><p class="experience-credit">项目资料：原旅行计划与${esc(item.operator)}；图片为项目景观参考${item.imageCredit?`，补充图片来自 <a href="${esc(item.imageSource)}" target="_blank" rel="noopener">${esc(item.imageCredit)}</a>`:item.id==='blue-lagoon'?'，蓝湖地貌图片来自 <a href="https://www.visitreykjanes.is/en/moya/gallery/index/index/myndir-fra-reykjanesi/natturan/blue-lagoon-nature-3-1" target="_blank" rel="noopener">Visit Reykjanes</a>':'，补充图片来自运营方官网'}。价格为计划预算。</p></div></article><a class="experience-back" href="#budget">← 返回旅行预算单</a></div>`;}
function selectExperiencePhoto(index){const gallery=$('.experience-gallery');if(!gallery)return;const item=experiences.find(x=>x.id===gallery.dataset.experience);if(!item)return;const next=(index%item.photos.length+item.photos.length)%item.photos.length,p=item.photos[next];gallery.dataset.photoIndex=String(next);$('#experience-photo').src=p.src;$('#experience-photo').alt=p.label;$('#gallery-caption').textContent=p.label;$('.gallery-count').textContent=`${next+1} / ${item.photos.length}`;$$('[data-gallery-photo]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===next)));}
document.addEventListener('click',event=>{const thumb=event.target.closest('[data-gallery-photo]'),arrow=event.target.closest('[data-gallery-step]');if(thumb)selectExperiencePhoto(Number(thumb.dataset.galleryPhoto));if(arrow)selectExperiencePhoto(Number($('.experience-gallery').dataset.photoIndex)+Number(arrow.dataset.galleryStep));});
document.addEventListener('keydown',event=>{if(event.target.closest?.('.experience-gallery')&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();selectExperiencePhoto(Number($('.experience-gallery').dataset.photoIndex)+(event.key==='ArrowRight'?1:-1));}});
